#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# S12 spike (ADR 0003): local iOS simulator builds as rnship-agent, with Xcode 26.3.
#   Q1  prebuild + pod install + an unsigned Release simulator build under `rnship sandbox
#       run`: does it work, and what stops it (hosts the proxy refuses, Xcode's own script
#       sandbox nesting, EPERM)?
#   Q2  does a simulator smoke (boot, install, launch, screenshot) need the agent's GUI
#       session? Headless = a LaunchDaemon with UserName, the path a reboot-proof tick takes.
#   Q3  local Release builds, as you: `eas build --local` vs prebuild + xcodebuild (unsigned,
#       simulator; signed archives wait for M6).
# iOS only. Run as YOUR macOS user, from a rn-ship-pipeline checkout of main, pushed to origin
# (the agent clones the public repo). Results land in docs/spikes/S12.results.env
# (gitignored). No secrets are involved, and no claude -p calls.

ROOT=$(cd "$(dirname "$0")/../.." && pwd)
PIPELINE_URL=https://github.com/passpier/rn-ship-pipeline
AGENT=rnship-agent
AGENT_HOME=/Users/$AGENT
AGENT_RNSHIP=$AGENT_HOME/rnship
AGENT_PATH=$AGENT_RNSHIP/node_modules/.bin:$AGENT_HOME/.local/node/bin:$AGENT_HOME/.local/bin:/opt/homebrew/bin:/usr/bin:/bin:/usr/sbin:/sbin
SHARED=/Users/Shared/rnship-s12 # scripts, logs, screenshots (yours, group $AGENT, 1770)
APP=$AGENT_HOME/apps/s12
WORK=${RNSHIP_FIXTURE_DIR:-$HOME/Home_Projects/rnship-s6-probe}
EAS="npx -y eas-cli@24.13.0" # the version the staging workflow pins
ENV_FILE=$ROOT/docs/spikes/S12.results.env

trap 'warn "stopped at line $LINENO. Fix the cause and re-run; finished stages are safe to repeat."' ERR

record() { write_env "$1" "$2"; }
fail() { warn "$1"; exit 1; }
minutes() { echo $(( (${1:-0} + 59) / 60 )); }

# as_agent CMD... runs CMD as rnship-agent via sudo (clones, installs, reads). Not for the
# questions: sudo keeps your bootstrap namespace, so CoreSimulator answers would be yours.
as_agent() {
  ( cd / && sudo -u "$AGENT" -H /usr/bin/env PATH="$AGENT_PATH" LANG=en_US.UTF-8 "$@" )
}
as_agent_sh() { as_agent /bin/sh -c "cd ~ && $1"; }
session_up() {
  sudo launchctl print "gui/$AGENT_UID" >/dev/null 2>&1 \
    && sudo test -e "$AGENT_HOME/Library/Keychains/login.keychain-db"
}
in_staff() { id -Gn "$AGENT" | tr ' ' '\n' | grep -x staff >/dev/null; }

# _env_dict prints the environment every job gets, as plist XML.
_env_dict() {
  printf '<key>EnvironmentVariables</key><dict>'
  printf '<key>HOME</key><string>%s</string>' "$AGENT_HOME"
  printf '<key>PATH</key><string>%s</string>' "$AGENT_PATH"
  printf '<key>LANG</key><string>en_US.UTF-8</string>'
  printf '<key>S12_SHARED</key><string>%s</string>' "$SHARED"
  printf '</dict>'
}

# _wait_done LABEL TIMEOUT waits for the job's done file, showing the minutes.
_wait_done() {
  local done="$SHARED/$1.done" waited=0
  while [[ ! -e "$done" ]] && (( waited < $2 )); do
    sleep 5; waited=$((waited + 5))
    (( waited % 60 == 0 )) && note "$((waited / 60)) min…"
  done
  [[ -e "$done" ]]
}

# run_headless LABEL TIMEOUT CMD... runs CMD once as a LaunchDaemon with UserName $AGENT:
# no GUI session involved, as a headless production tick would run. Log: $SHARED/LABEL.log.
run_headless() {
  local label=$1 timeout=$2; shift 2
  local job="dev.rnship.s12.$label" plist="/Library/LaunchDaemons/dev.rnship.s12.$label.plist"
  local arg args="" ok=0
  for arg in "$@"; do args+="<string>$arg</string>"; done
  sudo rm -f "$SHARED/$label.log" "$SHARED/$label.done"
  sudo launchctl bootout "system/$job" 2>/dev/null || true
  sudo tee "$plist" >/dev/null <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$job</string>
  <key>UserName</key><string>$AGENT</string>
  <key>GroupName</key><string>$AGENT</string>
  <key>InitGroups</key><true/>
  <key>WorkingDirectory</key><string>$AGENT_HOME</string>
  <key>ProgramArguments</key><array>
    <string>/bin/sh</string><string>-c</string><string>"\$@"; touch $SHARED/$label.done</string><string>sh</string>$args
  </array>
  $(_env_dict)
  <key>RunAtLoad</key><true/>
  <key>StandardOutPath</key><string>$SHARED/$label.log</string>
  <key>StandardErrorPath</key><string>$SHARED/$label.log</string>
</dict></plist>
PLIST
  sudo chown root:wheel "$plist" && sudo chmod 644 "$plist"
  if sudo launchctl bootstrap system "$plist"; then
    note "running headless (up to $((timeout / 60)) min); log: $SHARED/$label.log"
    _wait_done "$label" "$timeout" && ok=1
  else
    warn "bootstrap of the LaunchDaemon failed"
  fi
  sudo launchctl bootout "system/$job" 2>/dev/null || true
  sudo rm -f "$plist"
  (( ok ))
}

# run_in_agent_session LABEL TIMEOUT CMD... runs CMD once as a LaunchAgent in the agent's
# GUI session (the M3 path). Log: $SHARED/LABEL.log.
run_in_agent_session() {
  local label=$1 timeout=$2; shift 2
  local job="dev.rnship.s12.$label" plist="$AGENT_HOME/Library/LaunchAgents/dev.rnship.s12.$label.plist"
  local arg args="" ok=0
  for arg in "$@"; do args+="<string>$arg</string>"; done
  sudo rm -f "$SHARED/$label.log" "$SHARED/$label.done"
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo -u "$AGENT" mkdir -p "$AGENT_HOME/Library/LaunchAgents"
  sudo -u "$AGENT" tee "$plist" >/dev/null <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$job</string>
  <key>ProgramArguments</key><array>
    <string>/bin/sh</string><string>-c</string><string>"\$@"; touch $SHARED/$label.done</string><string>sh</string>$args
  </array>
  $(_env_dict)
  <key>RunAtLoad</key><true/>
  <key>StandardOutPath</key><string>$SHARED/$label.log</string>
  <key>StandardErrorPath</key><string>$SHARED/$label.log</string>
</dict></plist>
PLIST
  if sudo launchctl bootstrap "gui/$AGENT_UID" "$plist"; then
    note "running in $AGENT's GUI session (up to $((timeout / 60)) min); log: $SHARED/$label.log"
    _wait_done "$label" "$timeout" && ok=1
  else
    warn "bootstrap failed: is $AGENT still logged in (fast user switching)?"
  fi
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo rm -f "$plist"
  (( ok ))
}

# logval LABEL KEY: the last KEY=value line s12-step.sh printed for LABEL.
logval() { sed -n "s/^$2=//p" "$SHARED/$1.log" 2>/dev/null | tail -n1; }

# step_run RUNNER LABEL TIMEOUT MODE SCRIPT ARGS... runs one s12-step.sh job, then records
# S12_<LABEL> (ok, or fail:<exit>) and what the step saw. Succeeds if the step did.
step_run() {
  local runner=$1 label=$2 timeout=$3; shift 3
  local p rc
  p="S12_$(tr 'a-z-' 'A-Z_' <<<"$label")"
  "$runner" "$label" "$timeout" /bin/sh "$SHARED/s12-step.sh" "$label" "$@" \
    || { record "$p" "timeout"; return 1; }
  rc=$(logval "$label" exit)
  record "$p" "$([[ $rc == 0 ]] && echo ok || echo "fail:${rc:-?}")"
  record "${p}_MINUTES" "$(minutes "$(logval "$label" secs)")"
  record "${p}_REFUSED" "$(logval "$label" refused)"
  record "${p}_EPERM" "$(logval "$label" eperm)"
  record "${p}_NESTED_SANDBOX" "$(logval "$label" nested)"
  [[ -n "$(logval "$label" result)" ]] && record "${p}_RESULT" "$(logval "$label" result)"
  if [[ $rc != 0 ]]; then
    record "${p}_ERROR" "$(logval "$label" first_error)"
    note "last lines (full log: $AGENT_HOME/s12-$label.full.log):"
    sed -n '/^--- tail ---$/,$p' "$SHARED/$label.log" | tail -n +2 | sed 's/^/    /'
  fi
  [[ $rc == 0 ]]
}

# headless_session KEY: a headless answer is only decisive with the agent logged out.
headless_session() {
  if session_up; then
    warn "$AGENT is logged in, so its GUI session could help a headless job along."
    if confirm "Log $AGENT out now? (sudo launchctl bootout gui/$AGENT_UID; it has nothing to save)"; then
      sudo launchctl bootout "gui/$AGENT_UID" 2>/dev/null || true
      sleep 5
    fi
  fi
  record "$1" "$(session_up && echo up || echo down)"
}

need_session() {
  session_up && return 0
  say "$1 needs $AGENT's GUI session."
  step "Log in as $AGENT once (user switcher in the menu bar), then switch back to your account."
  pause "Press Enter when $AGENT is logged in"
  session_up || fail "$AGENT still isn't logged in"
}

TOTAL_STAGES=10

banner "S12: local iOS simulator builds as $AGENT"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
[[ $EUID -ne 0 && "$(id -un)" != "$AGENT" ]] || fail "run this as your own macOS user"
for c in jq git node npx xcodebuild xcrun pod sudo; do command -v "$c" >/dev/null || fail "missing $c"; done
node -e 'process.exit(+process.versions.node.split(".")[0] >= 24 ? 0 : 1)' || fail "need Node 24 (nvm use 24)"
XCODE=$(xcodebuild -version | sed -n 1p)
record S12_XCODE "$XCODE"
[[ $XCODE == "Xcode 26.3" ]] || warn "ADR 0003 assumes Xcode 26.3; this is $XCODE"
RUNTIME=$(xcrun simctl list -j runtimes | jq -r '[.runtimes[] | select(.isAvailable and .platform == "iOS" and (.version | startswith("26.3")))][0].identifier // empty')
[[ -n "$RUNTIME" ]] || fail "no iOS 26.3 simulator runtime: Xcode → Settings → Components"
record S12_RUNTIME "$RUNTIME"
say "sudo runs every agent step; enter your password once."
sudo -v
# Builds take a while and sudo forgets you after a few minutes, so keep it fresh until exit.
while sleep 60; do sudo -n true 2>/dev/null || exit; done &
SUDO_KEEPALIVE=$!
trap 'kill "$SUDO_KEEPALIVE" 2>/dev/null || true' EXIT
AGENT_UID=$(id -u "$AGENT" 2>/dev/null) || fail "no $AGENT user: run scripts/spikes/s0-identity.sh first"
dscl . -read "/Groups/$AGENT" >/dev/null 2>&1 && ! in_staff \
  || fail "$AGENT must have its own group, not staff: run scripts/acceptance/m3.sh stage 1 first"
[[ "$(as_agent node -v 2>/dev/null)" == v24.* ]] || fail "$AGENT has no Node 24 in ~/.local/node (S0)"
POD=$(as_agent pod --version 2>/dev/null) || fail "$AGENT can't run /opt/homebrew/bin/pod"
record S12_POD "$POD"
git -C "$ROOT" fetch -q origin main
[[ -z "$(git -C "$ROOT" status --porcelain)" ]] || fail "uncommitted changes in $ROOT: the agent runs what's on origin/main"
RNSHIP_SHA=$(git -C "$ROOT" rev-parse origin/main)
[[ "$(git -C "$ROOT" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "HEAD isn't origin/main: git push origin main (or pull) first"
[[ -d "$WORK/.git" ]] || fail "no fixture checkout at $WORK (set RNSHIP_FIXTURE_DIR)"
record S12_RNSHIP_SHA "$RNSHIP_SHA"
record S12_FIXTURE_SHA "$(git -C "$WORK" rev-parse HEAD)"
mkdir -p "$SHARED" && sudo chown "$(id -un):$AGENT" "$SHARED" && chmod 1770 "$SHARED"
note "Builds go to $AGENT's home: expect a few GB (DerivedData, Pods, a simulator)."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "rn-ship-pipeline for $AGENT"
say "$AGENT can't read your checkout, so it clones the public repo at ${RNSHIP_SHA:0:12}."
if sudo test -d "$AGENT_RNSHIP/.git"; then
  as_agent git -C "$AGENT_RNSHIP" fetch -q origin main
else
  as_agent git clone -q "$PIPELINE_URL" "$AGENT_RNSHIP"
fi
as_agent git -C "$AGENT_RNSHIP" checkout -q --detach "$RNSHIP_SHA"
as_agent_sh "cd rnship && npx -y pnpm@10.30.0 install --frozen-lockfile --reporter=silent"
[[ "$(as_agent git -C "$AGENT_RNSHIP" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "the agent's checkout isn't at $RNSHIP_SHA"
as_agent /bin/sh -c 'command -v rnship' >/dev/null || fail "rnship isn't on the agent's PATH"
say "Installed in $AGENT_RNSHIP."
# Xcode decides which simulator runtimes fit its SDK from a per-user index that the Xcode app
# downloads (SDKToSimulatorIndexMapping.plist). Without it, SDK 26.2 (23C57) only takes runtime
# 23C57, so the installed 26.3.1 (23D8133) reads as "iOS 26.2 is not installed" and no
# simulator destination exists. xcodebuild doesn't fetch it, so the agent gets yours: public data.
SIM_INDEX=Library/Developer/Xcode/SDKToSimulatorIndexMapping.plist
[[ -f "$HOME/$SIM_INDEX" ]] || fail "no ~/$SIM_INDEX: open Xcode once, then re-run"
as_agent mkdir -p "$AGENT_HOME/$(dirname "$SIM_INDEX")"
sudo install -o "$AGENT" -g "$AGENT" -m 644 "$HOME/$SIM_INDEX" "$AGENT_HOME/$SIM_INDEX"
record S12_SIM_INDEX copied
say "Copied Xcode's SDK-to-simulator index to $AGENT."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fixture clone and the agent's scripts"
if sudo test -e "$APP"; then
  if confirm "An earlier S12 run left ~/apps/s12. Delete it and its build, and start fresh?"; then
    as_agent rm -rf "$APP" "$AGENT_HOME/s12-dd"
  fi
fi
if ! sudo test -e "$APP"; then
  BUNDLE=$SHARED/fixture.bundle
  rm -f "$BUNDLE" && git -C "$WORK" bundle create "$BUNDLE" HEAD 2>/dev/null && chmod 644 "$BUNDLE"
  as_agent git clone -q "$BUNDLE" "$APP"
  note "npm ci in ~/apps/s12, outside the sandbox (as M3 does)…"
  as_agent_sh "cd apps/s12 && npm ci --no-audit --no-fund --loglevel=error"
fi

# s12-step.sh LABEL sandboxed|plain SCRIPT ARGS... is the job every stage runs. It copies
# SCRIPT into the agent's home (the sandbox can't read /Users/Shared), runs it in the fixture
# clone with its output in ~/s12-LABEL.full.log, and prints a summary the wizard reads.
cat > "$SHARED/s12-step.sh" <<'STEP'
#!/bin/sh
set -u
label=$1 mode=$2 script=$3; shift 3
full="$HOME/s12-$label.full.log"
cp "$S12_SHARED/$script" "$HOME/.s12-$script" || { echo "exit=copy"; exit 1; }
cd "$HOME/apps/s12" || { echo "exit=cd"; exit 1; }
echo "groups=$(id -Gn)"
start=$(date +%s)
if [ "$mode" = sandboxed ]; then
  rnship sandbox run --home "$HOME" -- /bin/sh "$HOME/.s12-$script" "$@" > "$full" 2>&1
else
  /bin/sh "$HOME/.s12-$script" "$@" > "$full" 2>&1
fi
rc=$?
for f in "$HOME"/s12-"$label"*.png; do [ -e "$f" ] && cp "$f" "$S12_SHARED/" && chmod 644 "$S12_SHARED/$(basename "$f")"; done
echo "exit=$rc"
echo "secs=$(( $(date +%s) - start ))"
echo "refused=$(grep -o 'rnship sandbox: refused [^ ]*' "$full" | cut -d' ' -f4 | sort -u | paste -sd, -)"
echo "nested=$(grep -q 'sandbox_apply' "$full" && echo yes || echo no)"
echo "eperm=$(grep -c 'Operation not permitted' "$full")"
echo "first_error=$(grep -m1 -E '(^|[[:space:]])(error|Error|ERROR)[: ]' "$full" | cut -c1-200)"
grep '^result=' "$full" | tail -n1
echo "--- tail ---"
tail -n 15 "$full"
STEP

cat > "$SHARED/fetch.sh" <<'SH'
#!/bin/sh
# The native iOS project and its pods. Both run code the agent can change (config plugins,
# podspecs), so the wizard runs this under the validation sandbox first.
set -eu
export CI=1
npx --no-install expo prebuild --platform ios --no-install --clean
cd ios && pod install
SH

cat > "$SHARED/build.sh" <<'SH'
#!/bin/sh
# An unsigned Release build for the simulator: the JS bundle is embedded, so no Metro.
# Extra args are build settings. DerivedData goes to $S12_DD, else ~/s12-dd.
set -eu
cd ios
ws=$(ls -d *.xcworkspace | head -n1)
exec xcodebuild -workspace "$ws" -scheme "${ws%.xcworkspace}" -configuration Release \
  -sdk iphonesimulator -destination 'generic/platform=iOS Simulator' \
  -derivedDataPath "${S12_DD:-$HOME/s12-dd}" CODE_SIGNING_ALLOWED=NO "$@" build
SH

cat > "$SHARED/smoke.sh" <<'SH'
#!/bin/sh
# A fresh simulator: boot, install and launch the build, screenshot, check it's still up.
set -u
label=$1
udid=""
cleanup() { [ -n "$udid" ] && { xcrun simctl shutdown "$udid" >/dev/null 2>&1; xcrun simctl delete "$udid" >/dev/null 2>&1; }; }
trap cleanup EXIT
at() { echo "result=$1"; exit 1; }
app=$(ls -d "$HOME"/s12-dd/Build/Products/Release-iphonesimulator/*.app 2>/dev/null | head -n1)
[ -n "$app" ] || at no_app
bid=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleIdentifier' "$app/Info.plist") || at no_bundle_id
pick=$(xcrun simctl list -j runtimes | node -e 'const j=JSON.parse(require("fs").readFileSync(0,"utf8"));const r=j.runtimes.find(r=>r.isAvailable&&r.platform==="iOS"&&r.version.startsWith("26.3"));const d=r&&(r.supportedDeviceTypes||[]).find(t=>t.productFamily==="iPhone");if(!d)process.exit(1);console.log(r.identifier,d.identifier)') || at no_runtime
set -- $pick
udid=$(xcrun simctl create "rnship-s12-$label" "$2" "$1") || at create
xcrun simctl bootstatus "$udid" -b || at boot
xcrun simctl install "$udid" "$app" || at install
xcrun simctl launch "$udid" "$bid" || at launch
sleep 10
xcrun simctl io "$udid" screenshot "$HOME/s12-smoke-$label.png" || at screenshot
xcrun simctl spawn "$udid" launchctl list | grep "$bid" >/dev/null || at exited
echo "result=ok"
SH
chmod 755 "$SHARED"/*.sh
say "Wrote s12-step.sh, fetch.sh, build.sh and smoke.sh to $SHARED (yours; $AGENT can read, not change)."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Q1: prebuild + pod install, headless, sandboxed"
say "First the dependency fetch alone, under rnship sandbox run and its network allowlist."
headless_session S12_FETCH_GUI_SESSION
if ! step_run run_headless fetch-sandboxed 3600 sandboxed fetch.sh; then
  warn "The sandboxed fetch failed. Refused hosts: $(logval fetch-sandboxed refused)"
  say "Fetching once more outside the sandbox, so the build can still be tested."
  step_run run_headless fetch-plain 3600 plain fetch.sh || fail "the fetch fails outside the sandbox too: see $SHARED/fetch-plain.log"
fi
record S12_HEADLESS_GROUPS "$(logval fetch-sandboxed groups)"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Q1: Release simulator build, headless, sandboxed"
note "An RN release build takes 5–20 minutes."
headless_session S12_BUILD_GUI_SESSION
BUILD_ARGS=()
if step_run run_headless build-headless 5400 sandboxed build.sh; then
  BUILT=headless
elif [[ "$(logval build-headless nested)" == yes ]]; then
  warn "Xcode's script sandbox couldn't nest inside ours (sandbox_apply)."
  say "Retrying with ENABLE_USER_SCRIPT_SANDBOXING=NO."
  BUILD_ARGS=(ENABLE_USER_SCRIPT_SANDBOXING=NO)
  step_run run_headless build-headless-noscriptsandbox 5400 sandboxed build.sh "${BUILD_ARGS[@]}" \
    && BUILT=headless-noscriptsandbox || BUILT=""
else
  BUILT=""
fi
if [[ -z "$BUILT" ]]; then
  warn "The headless build failed. Trying the same build in $AGENT's GUI session."
  need_session "The GUI-session build"
  step_run run_in_agent_session build-gui 5400 sandboxed build.sh ${BUILD_ARGS[@]+"${BUILD_ARGS[@]}"} \
    && BUILT=gui || fail "the build fails in the GUI session too: see $SHARED/build-gui.log"
fi
record S12_BUILT_BY "$BUILT"
record S12_APP_KB "$(as_agent_sh 'du -sk s12-dd/Build/Products/Release-iphonesimulator/*.app | cut -f1 | head -n1')"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Q2: simulator smoke, headless, sandboxed"
headless_session S12_SMOKE_HEADLESS_GUI_SESSION
step_run run_headless smoke-headless 900 sandboxed smoke.sh headless \
  || warn "headless smoke: $(logval smoke-headless result)"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Q2: simulator smoke, in $AGENT's GUI session, sandboxed"
need_session "This smoke"
step_run run_in_agent_session smoke-gui 900 sandboxed smoke.sh gui \
  || warn "GUI-session smoke: $(logval smoke-gui result)"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Screenshots"
SHOTS=0
for s in headless gui; do
  if [[ -e "$SHARED/s12-smoke-$s.png" ]]; then open "$SHARED/s12-smoke-$s.png"; SHOTS=$((SHOTS + 1)); fi
done
if (( SHOTS == 0 )); then
  note "No smoke got as far as a screenshot."
  record S12_SCREENSHOT_OK none
else
  say "Opened $SHOTS screenshot(s) from $SHARED."
  if confirm "Does each one show the fixture app's screen (not a crash or the home screen)?"; then
    record S12_SCREENSHOT_OK yes
  else
    record S12_SCREENSHOT_OK no
  fi
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Q3: local Release paths, as you (unsigned, simulator)"
REL=$(mktemp -d -t rnship-s12-rel)
say "Two fresh clones of the fixture in $REL; nothing is pushed."
# rel_step KEY LOG CMD... runs CMD, then records KEY ok|fail:<exit>, its minutes and first error.
rel_step() {
  local key=$1 log=$2 start rc=0; shift 2
  start=$(date +%s)
  "$@" > "$log" 2>&1 || rc=$?
  record "$key" "$([[ $rc == 0 ]] && echo ok || echo "fail:$rc")"
  record "${key}_MINUTES" "$(minutes $(( $(date +%s) - start )))"
  if (( rc != 0 )); then
    record "${key}_ERROR" "$(grep -m1 -E '(^|[[:space:]])(error|Error|ERROR)[: ]' "$log" | cut -c1-200)"
    tail -n 15 "$log" | sed 's/^/    /'
  fi
  return 0
}
for d in xcodebuild eas; do
  git clone -q "$WORK" "$REL/$d"
  (cd "$REL/$d" && npm ci --no-audit --no-fund --loglevel=error)
done

say "B: expo prebuild + pod install + xcodebuild, the same build the agent ran."
rel_step S12_REL_XCODEBUILD "$REL/xcodebuild.log" /bin/sh -c "cd '$REL/xcodebuild' && \
  sh '$SHARED/fetch.sh' && S12_DD='$REL/dd' sh '$SHARED/build.sh'"
note "B: $(sed -n 's/^S12_REL_XCODEBUILD=//p' "$ENV_FILE" | tail -n1)"

say "A: eas build --local, with a throwaway simulator profile."
EAS_OK=yes
if ! command -v fastlane >/dev/null; then
  warn "eas build --local needs fastlane for iOS, and it isn't installed."
  if confirm "Install it with brew install fastlane?"; then brew install fastlane || EAS_OK=no; else EAS_OK=no; fi
fi
record S12_REL_EAS_FASTLANE "$(command -v fastlane >/dev/null && fastlane --version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n1 || echo missing)"
if [[ $EAS_OK == yes ]] && ! (cd "$REL/eas" && $EAS whoami >/dev/null 2>&1); then
  warn "eas-cli isn't logged in. Run: $EAS login"
  EAS_OK=no
fi
if [[ $EAS_OK == yes ]]; then
  (cd "$REL/eas" && node -e '
const fs = require("fs");
const j = fs.existsSync("eas.json") ? JSON.parse(fs.readFileSync("eas.json", "utf8")) : {};
j.cli = { appVersionSource: "local", ...j.cli };
j.build = { ...j.build, "s12-sim": { distribution: "internal", ios: { simulator: true } } };
fs.writeFileSync("eas.json", JSON.stringify(j, null, 2) + "\n");' \
    && git add eas.json && git -c user.name=s12 -c user.email=s12@localhost commit -qm "S12: simulator profile")
  rel_step S12_REL_EAS_LOCAL "$REL/eas.log" /bin/sh -c "cd '$REL/eas' && \
    $EAS build --local --platform ios --profile s12-sim --non-interactive --output '$REL/eas-app.tar.gz'"
  note "A: $(sed -n 's/^S12_REL_EAS_LOCAL=//p' "$ENV_FILE" | tail -n1)"
else
  record S12_REL_EAS_LOCAL skipped
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Disk use"
record S12_DISK "$(as_agent_sh 'du -sh s12-dd apps/s12/ios/Pods Library/Developer/CoreSimulator Library/Caches/CocoaPods 2>/dev/null' | awk '{sub(/^\/Users\/[^\/]+\//, "", $2); printf "%s%s=%s", (NR > 1 ? "," : ""), $2, $1}')"
record S12_REL_DISK "$(du -sh "$REL" | cut -f1)"

# ── Summary ───────────────────────────────────────────────────────────────
finish
grep '^S12_' "$ENV_FILE" | sed 's/^/    /'
say ""
note "Wanted: FETCH_SANDBOXED ok (else its REFUSED lists the hosts to decide on) · BUILT_BY headless"
note "· SMOKE_HEADLESS ok decides headless; if only SMOKE_GUI is ok, the agent keeps its GUI session"
note "· SCREENSHOT_OK yes · REL_XCODEBUILD vs REL_EAS_LOCAL: which works, and the minutes."
say ""
say "Left in place for inspection:"
step "$SHARED (job logs, screenshots), $AGENT_HOME/s12-*.full.log (full output)"
step "$APP, $AGENT_HOME/s12-dd, and $REL"
note "Clean up later with:"
note "  sudo -u $AGENT rm -rf $APP $AGENT_HOME/s12-dd $AGENT_HOME/s12-*.full.log $AGENT_HOME/s12-*.png $AGENT_HOME/.s12-*"
note "  rm -rf $REL $SHARED"
printf '\n'
